// Serves both typed commands AND the AI Agent button
// Knowledge base: 434 chunks from game dev tutorials/GDC talks

// ── KNOWLEDGE BASE (bundled — no external DB needed) ────────────────────────
const KB = [{"t":"physics","f":"Cannon-es uses gravity of 9.82 meters per second squared as the standard Earth gravity value"},{"t":"physics","f":"Cannon Box shape uses half-extents: a 1x1x1 Three.js BoxGeometry corresponds to a Cannon Box(0.5, 0.5, 0.5)"},{"t":"physics","f":"Cannon physics body for a dynamic object uses mass of 1 for standard interactive rigid bodies"},{"t":"physics","f":"Physics world step uses clock.getDelta() to advance simulation by the elapsed time each frame"},{"t":"rendering","f":"Two engines run simultaneously: Cannon for physics simulation and Three.js for 3D rendering; each frame you copy Cannon body positions/quaternions to Three.js mesh positions/quaternions"},{"t":"physics","f":"cannon-es version 0.18 is the maintained fork of the original cannon.js physics library, installed via npm install cannon-es --save-dev"},{"t":"npc","f":"AI controller requires calling super::OnPossess(Pawn) as the first action in the OnPossess override to ensure downstream logic in the AI controller base class executes properly \u2014 skipping super calls causes weird behavior"},{"t":"npc","f":"AI controller uses OnPossess(APawn* Pawn) virtual void override to take control of a pawn, with a Cast to the specific NPC character class to validate the pawn type before executing AI logic"},{"t":"npc","f":"NPC character class is derived from a base character class (TFCharacter), and the AI controller is a separate class that possesses and controls the NPC pawn \u2014 separation of character definition from AI behavior"},{"t":"npc","f":"NPC roaming requires a navigation mesh (nav mesh) that defines walkable areas \u2014 the nav mesh bounds volume covers the entire map including vertical space for multi-level navigation"},{"t":"npc","f":"Roaming AI pattern: separate AI Controller (brain) from AI Character (body) \u2014 controller issues movement commands, character executes them"},{"t":"npc","f":"Simple roaming NPC behavior: on begin play trigger 'start roaming' custom event that picks a random navigable location from the nav mesh and moves the AI to it"},{"t":"npc","f":"Nav mesh bounds volume needs extra vertical height to cover stairs and multi-floor areas \u2014 expand Z-axis beyond ground level"},{"t":"npc","f":"Dialogue system uses a Queue (FIFO - first in first out) data structure to manage sentences, loading all sentences into the queue when dialogue starts and dequeuing them as the player reads through"},{"t":"npc","f":"Dialogue data is stored in a separate non-MonoBehaviour class containing a public string array for sentences and a public string for NPC name, passed into a DialogueManager to start conversations"},{"t":"npc","f":"Dialogue UI consists of a dialog box image, two text objects (NPC name + dialogue text), and a continue button, built with standard Unity UI tools"},{"t":"physics","f":"Gravity set to -9.82 in the Y direction for realistic physics simulation"},{"t":"physics","f":"Ground body uses type 'static' with geometric plane shape, rotated 90 degrees to be horizontal"},{"t":"vehicles","f":"Car body mass set to 5, positioned at (0, 6, 0) to spawn above ground"},{"t":"vehicles","f":"Cannon.js RigidVehicle class handles vehicle creation including hinge constraints for wheel steering"},{"t":"vehicles","f":"Wheels use sphere shape with angular dampening, offset downward to avoid intersection with car body"},{"t":"rendering","f":"Cannon.js debugger creates green wireframe overlay on physics objects for visualization"},{"t":"physics","f":"Animation loop updates both Cannon debugger and physics world each frame for sync"},{"t":"rendering","f":"WebGL renders graphics at target 60fps using GPU-accelerated matrix multiplication/linear algebra"},{"t":"rendering","f":"3D rendering pipeline: vertices (x,y,z points) -> primitives (triangles) -> lighting/shadows -> rasterization (3D to 2D pixel projection)"},{"t":"rendering","f":"Shaders are GPU functions that customize the rendering pipeline - vertex shaders process vertex data, fragment shaders calculate per-pixel color"},{"t":"rendering","f":"WebGL is based on OpenGL (established 1992) and runs inside HTML canvas element without external plugins"},{"t":"rendering","f":"Three.js abstracts WebGL shader writing - allows 3D graphics without hand-writing GLSL shaders"},{"t":"city","f":"Forest vegetation requires models of different heights to simulate different layers of the forest canopy"},{"t":"city","f":"For terrain vegetation, 5000-10000 tree models are used to cover a terrain surface"},{"t":"rendering","f":"Terrain texture layers stack with higher layers covering lower layers, each layer supports modifiers like height (max height, max falloff) and slope for placement control"},{"t":"rendering","f":"Rock textures should be placed using a slope modifier to automatically appear on steep terrain slopes"},{"t":"rendering","f":"Terrain grass uses 4 grass models mixed automatically via spine details tool with target density controlling frequency of each model"},{"t":"rendering","f":"Stamp-based terrain sculpting uses adjustable brush size and stamp height with 'stamp from current height' set to 1 for additive stamping"},{"t":"rendering","f":"Increasing splat map resolution and map resolution improves terrain texture detail quality"},{"t":"npc","f":"NPC crowd systems use Zone Graphs with Zone Shapes to define walkable areas, with lane profiles containing forward and backward lanes"},{"t":"npc","f":"NPC crowd agents require MassAgent component with entity config containing: agent capsule collision sync, agent movement (mass-to-actor), and agent orientation align (mass-to-actor)"},{"t":"npc","f":"Crowd NPC lane profile width set to 100 units for pedestrian paths"},{"t":"npc","f":"Crowd NPCs use 2 lanes per path - one forward, one backward - for bidirectional pedestrian flow"},{"t":"npc","f":"Mass Entity crowd system uses MassCrowd plugin (MCrow) for large-scale NPC simulation"},{"t":"npc","f":"Crowd NPC characters need capsule collider positioning - mesh placed inside capsule with correct orientation"},{"t":"npc","f":"Simple crowd NPCs can use a single looping forward walk animation as their base animation blueprint"},{"t":"rendering","f":"Terrain brush size of ~400 for coarse/large terrain features, ~200 for smaller detail passes"},{"t":"rendering","f":"Grass detail distance set to 250 units to make grass visible from further away"},{"t":"rendering","f":"Fog density of 0.0045 provides good distance obscuring while looking natural"},{"t":"rendering","f":"Fog color sampled from low horizon of skybox creates cohesive sky-to-ground fade"},{"t":"rendering","f":"Grass healthy color sampled from lighter parts of base terrain texture, dry color from darker parts"},{"t":"rendering","f":"Mass place 15000 trees on terrain for dense forest coverage"},{"t":"rendering","f":"Fog used to hide LOD pop-in and grass detail distance cutoff"},{"t":"npc","f":"AI NPC conversation system requires ~28GB download for local inference, suggesting large language model running client-side"},{"t":"npc","f":"AI NPC voice response latency is variable and noticeable \u2014 sometimes 1-3 seconds delay between player speech and NPC reply"},{"t":"npc","f":"AI NPCs maintain consistent personality traits across a conversation \u2014 a hostile NPC stays hostile, a dismissive one stays dismissive"},{"t":"npc","f":"AI NPCs can contextually respond to environment \u2014 acknowledging heat, traffic, city crowding \u2014 without scripted triggers"},{"t":"city","f":"Demo city has sidewalks wide enough for 2+ NPCs side by side, vehicle traffic on roads, and stairway geometry on sidewalks"},{"t":"npc","f":"NPCs walk along sidewalks autonomously while holding props (coffee cup) and can be approached mid-walk for conversation"},{"t":"rendering","f":"Demo world has visible boundary walls ('Matrix wall') \u2014 hard invisible collision bounds at world edge"},{"t":"vehicles","f":"Car can control angular velocity while in the air to perform flip tricks"},{"t":"rendering","f":"React Three Fiber project with cannon.js physics is 4-5 files total for a complete race track with colliders"},{"t":"rendering","f":"Use Suspense component to wrap 3D asset loading in React Three Fiber"},{"t":"rendering","f":"Environment component creates 3D background from an environment map texture file"},{"t":"rendering","f":"OrbitControls component enables mouse-controlled camera with a Target property defining look-at point"},{"t":"vehicles","f":"Cannon.js used as physics engine for car racing with colliders on trees, signs, and ramps"},{"t":"rendering","f":"All Three.js/R3F hooks must be used inside the Canvas component \u2014 scene logic goes in child components"},{"t":"physics","f":"cannon-es (fork of cannon.js) uses a World object equivalent to Three.js's Scene \u2014 two engines run simultaneously: cannon for physics simulation and Three.js for 3D rendering"},{"t":"physics","f":"Gravity is set via new CANNON.World() with gravity value 9.82 m/s\u00b2 (Earth gravity), and the world is stepped each frame using world.step(delta) where delta comes from a Three.js Clock"},{"t":"physics","f":"CANNON.Box uses half-extents: a Three.js BoxGeometry(1,1,1) maps to new CANNON.Box(0.5, 0.5, 0.5), and the body is created with mass:1 then added to the world via world.addBody()"},{"t":"physics","f":"Each frame, sync physics to visuals by copying: cubeMesh.position.set(cubeBody.position.x, cubeBody.position.y, cubeBody.position.z) and cubeMesh.quaternion.copy(cubeBody.quaternion)"},{"t":"physics","f":"Without a ground plane body in the physics world, rigid bodies with gravity will fall infinitely \u2014 a floor mesh visible in Three.js does not automatically create a physics collider"},{"t":"physics","f":"cannon-es is installed via 'npm install cannon-es --save-dev' (version 0.18.x) and is a maintained fork of the original abandoned cannon.js library"},{"t":"npc","f":"AI Controller constructor requires FObjectInitializer as a const reference parameter, matching the base AAIController constructor signature"},{"t":"npc","f":"OnPossess is a virtual void override taking an APawn* pointer, used as the entry point where the AI controller takes over a pawn"},{"t":"npc","f":"Super::OnPossess(InPawn) must be called first in the OnPossess override to ensure downstream logic in the base AAIController executes properly, preventing undefined behavior"},{"t":"npc","f":"Store a private pointer to the NPC character class (ControlledPawn) initialized as nullptr, then assign it in OnPossess using Cast<ANPCCharacter>(InPawn) to verify the pawn type"},{"t":"npc","f":"After successful cast in OnPossess, retrieve the behavior tree from the NPC using ControlledPawn->GetBehaviorTree() and store it as a const UBehaviorTree* pointer"},{"t":"npc","f":"The NPC character class is derived from a shared base character class (TFCharacter), allowing both player and NPC characters to share common functionality"},{"t":"npc","f":"AI controller header uses sections private/protected/public, includes the NPC character header for the cast, and the ControlledPawn pointer does not necessarily need a UPROPERTY macro"},{"t":"npc","f":"Nav Mesh Bounds Volume actor defines walkable area for AI navigation; toggle visibility with P key to see green overlay of navigable surfaces"},{"t":"npc","f":"AI Controller blueprint class serves as the 'brain' assigned to an AI character via the AI Controller Class property in the character's Details panel"},{"t":"npc","f":"Roaming NPC uses Get Random Reachable Point in Navigable Radius node with the controlled pawn's location as origin to pick random destinations"},{"t":"npc","f":"Get Controlled Pawn node returns a Pawn object reference; pipe its return value through Get Actor Location to obtain XYZ world coordinates as the navigation origin"},{"t":"npc","f":"Nav Mesh Bounds Volume scale of 15x15x15 via Details panel creates a large navigable cube; height must cover vertical geometry like stairs for multi-floor navigation"},{"t":"npc","f":"AI character created by duplicating BP_ThirdPersonCharacter and reassigning its AI Controller Class from default to a custom controller blueprint"},{"t":"physics","f":"2D platformer uses trap collision detection where hitting any trap triggers player death and level restart"},{"t":"physics","f":"Moving platforms are used as timed obstacles that the player must wait for before proceeding"},{"t":"npc","f":"Collectible item system uses a UI counter in the top-left corner tracking collected cherry count per level"},{"t":"physics","f":"Level transition triggers load the next scene when the player reaches the end point of a level"},{"t":"physics","f":"Unity 2D platformer uses C# scripts edited in Visual Studio Community IDE with Unity autocompletion support"},{"t":"interior","f":"Unity 6 terrain tiles are massive in scale \u2014 a single tile is large enough that a player cannot traverse it in a 10-20 minute play session, so developers should focus on one tile before expanding"},{"t":"interior","f":"Build out one terrain tile completely (layers, textures, topology) before adding neighboring tiles, because adding layers after creating multiple tiles requires manually adding layers to each tile separately"},{"t":"tps","f":"Unity 6 HDRP template project includes built-in third and first person controllers; free alternatives from Unity Technologies are available on Asset Store by searching 'third person'"},{"t":"interior","f":"Terrain painting uses two primary controls: brush size and opacity, where opacity controls the influence level (strength) of the brush stroke on terrain height"},{"t":"interior","f":"Unity Shader Graph package includes importable 'production ready shaders' samples containing pre-built textures, prefabs, and rock assets that can be used as terrain layers"},{"t":"interior","f":"In Unity 6 HDRP, use File > New Scene > Basic Outdoors to get a scene with pre-built volumetric clouds and outdoor lighting setup"},{"t":"npc","f":"A Queue<string> (FIFO collection from System.Collections namespace) is used to store dialogue sentences, allowing sequential display by loading sentences from the front of the queue as the player progresses through dialogue."},{"t":"npc","f":"Dialogue data is stored in a separate non-MonoBehaviour class marked with [System.Serializable] attribute containing a public string[] sentences array and a public string name field, allowing it to appear in the Unity Inspector for editing."},{"t":"npc","f":"The architecture uses three scripts: DialogueManager (processes queue and displays text on an empty GameObject), Dialogue (serializable data class with name + sentences), and DialogueTrigger (attached to NPC/interactable to initiate conversation)."},{"t":"npc","f":"The dialogue UI consists of a Canvas containing an Image (dialog box), two Text objects (NPC name and dialogue text), and a Continue button, all built with Unity's standard UI tools."},{"t":"npc","f":"The Queue is initialized in Start() as 'sentences = new Queue<string>()' and kept as a private variable on the DialogueManager, with sentences enqueued when a new dialogue starts and dequeued as the player clicks continue."},{"t":"physics","f":"Cannon.js world gravity is set to -9.82 in the Y direction to simulate Earth gravity"},{"t":"physics","f":"Ground body uses type 'static' with a geometric plane shape, rotated 90 degrees to be horizontal instead of vertical"},{"t":"physics","f":"Cannon.js debugger takes the Three.js scene and physics world as arguments and creates green wireframe overlays on each physics object for visualization"},{"t":"vehicles","f":"Car body is created with mass=5 and positioned at (0,6,0) above ground, then wrapped in a Cannon.js RigidVehicle class that handles vehicle-specific physics"},{"t":"vehicles","f":"Wheels are sphere shapes with 'wheel' material type, offset downward to avoid intersecting the car body, with angular dampening applied"},{"t":"vehicles","f":"RigidVehicle.addWheel() internally adds hinge constraints so wheels turn correctly; requires wheel body, position, axis, and direction parameters"},{"t":"physics","f":"Animation loop must call update on both the Cannon.js debugger and the physics world every frame to keep physics and rendering in sync"},{"t":"city","f":"Gaia world generation uses a 4-step pipeline: 1) create World Designer in Gaia Manager, 2) generate world (stamps terrain), 3) spawn biome (populates vegetation/objects), 4) create runtime (enables gameplay)"},{"t":"city","f":"Gaia separates terrain shape generation (stamp step) from biome population (spawn step), allowing terrain geometry and object placement to be independently configured"},{"t":"city","f":"Gaia uses a 'stamp' system to apply heightmap and sculpting data onto Unity terrain tiles, generating landmasses like islands from predefined or procedural templates"},{"t":"npc","f":"ConvAI NPCs in UE5 generate real-time dynamic dialogue responses to player questions using generative AI, with each NPC maintaining a distinct personality and emotional state (angry car owner, concerned worker, indifferent bystander)"},{"t":"npc","f":"ConvAI NPCs maintain contextual awareness of world events (tank hit by lightning, flipped into air) and reference them coherently in unscripted voice conversations with the player"},{"t":"npc","f":"NPCs are assigned occupational roles (construction crew supervisor, investigator, civilian driver) that constrain their dialogue priorities \u2014 e.g. construction NPC only cares about crew safety, car owner NPC fixates on vehicle damage"},{"t":"city","f":"The UE5 ConvAI demo features a drivable urban street environment with civilian vehicles, construction zones, and destructible/interactive elements like tanks subject to physics events"},{"t":"physics","f":"Physics simulation triggers narrative events: a tank asset is struck by lightning and flips into the air, colliding with a civilian car \u2014 these physics outcomes become the shared context for all NPC conversations"},{"t":"vehicles","f":"Vehicle damage from physics events (tank flipping onto a car) persists in the world and NPCs reference the specific damage state \u2014 car owner NPC expresses anger about their damaged vehicle and refuses medical help"},{"t":"npc","f":"Player initiates NPC conversations with natural speech input and NPCs respond with generated voice audio in real-time, supporting multi-turn dialogue (follow-up questions like 'are you okay' and 'do you want to go to the hospital')"},{"t":"dungeon","f":"Pseudo-random number generators use a seed value fed into a formula to produce a deterministic sequence of numbers; same seed always produces the same sequence. System time is commonly used as seed for unique results each run."},{"t":"dungeon","f":"Binding of Isaac dungeon generation: start with default starting room, randomly select one of 4 sides to place next room, pick a random room from predefined layout collection, repeat until enough rooms placed, then place boss room, then optionally scatter random elements (chests, items, special objects) inside rooms."},{"t":"dungeon","f":"Random generation uses predefined elements (pre-designed rooms, objects) assembled in random configurations. Procedural generation creates entirely original content algorithmically. These are distinct approaches despite being used interchangeably."},{"t":"dungeon","f":"Random generation requires developers to create large amounts of predefined content (room layouts, object placements) beforehand to ensure variety. Procedural generation avoids this by algorithmically creating content at runtime."},{"t":"dungeon","f":"Procedural generation of worlds (Minecraft, Terraria style) relies on computer-generated noise functions rather than predefined room stitching, enabling creation of original terrain and content the developers never manually designed."},{"t":"dungeon","f":"Destructible terrain uses a dictionary with tile coordinates as keys and tile health as values; when health reaches zero the tile is removed from the tilemap. A level manager script handles tile placement and damage requests from player controller and other damage sources."},{"t":"dungeon","f":"Base tile size is 8x8 pixels for a minimalist pixel art aesthetic, chosen specifically to reduce art production time and allow focus on technical systems."},{"t":"dungeon","f":"Cave generation uses a modular noise-based system with 'World Gen Rules' (custom resource type) that define conditions, values, and thresholds. The level manager loops through world coordinates for every rule and applies them based on conditions, enabling different caves, formations, and biomes."},{"t":"dungeon","f":"Color palette shader takes each pixel's color and shifts it to the nearest color in a predefined palette (modified Dawnbringer 32 palette from lospec.com), creating banded lighting effects as lights dim and a crunchy retro look."},{"t":"dungeon","f":"Game structure replaces conventional roguelike floors/levels/rooms with a single large procedurally generated cave system. Deeper levels spawn different features, tested via a debug teleport view."},{"t":"dungeon","f":"Traversal items include bombs (area destruction + weapon), ropes (vertical traversal + weapon), and flares (light up dark areas, inspired by Deep Rock Galactic), all interacting with the destructible tile system."},{"t":"dungeon","f":"Room placement uses spawn-then-separate: spawn randomly sized prefab rooms, detect overlaps, push overlapping rooms apart based on center-of-mass direction. Repeat until all rooms are separated. If separation fails, re-run with different initial placements."},{"t":"dungeon","f":"Rooms are prefab-based with predefined doors marked as 'necessary' (green) or 'optional' (yellow). A pathfinding algorithm connects all doors between separated rooms via corridors."},{"t":"dungeon","f":"Union-Find algorithm prevents isolated room islands: maintain sets/trees of connected nodes where each tree root is the lowest node value. When merging trees, update all nodes to the new lowest value. Continue connecting until all rooms share one set."},{"t":"dungeon","f":"Multi-floor connectivity uses stair rooms that span exactly 2 floors. Union-Find tracks which floors are connected, and stair rooms are added iteratively until all floors belong to one connected set."},{"t":"dungeon","f":"The 3D algorithm is a direct extension of a 2D prototype: same overlap-separation and pathfinding-based corridor connection, but rooms are placed in 3D space and corridors are 3D hallways."},{"t":"dungeon","f":"Algorithm order: (1) place random rooms, (2) separate overlapping rooms, (3) place stair rooms connecting floors via Union-Find, (4) connect same-floor rooms with pathfinding corridors via Union-Find until fully connected."},{"t":"dungeon","f":"Procedural generation requires constraints to prevent unplayable results \u2014 pure random output produces white noise (random blocks everywhere with no terrain contour). Constraints ensure consistent surface materials, terrain flow, and structural coherence."},{"t":"dungeon","f":"Procedural generation design principle: balance enough variants to create unique/fun experiences while mitigating generation of unplayable configurations. Even a 1% chance of unplayability means 1 in 100 players gets a broken experience."},{"t":"dungeon","f":"Spawn validation is critical: if a player spawns surrounded by impassable material (e.g., stone in Terraria) with no escape, the world is unplayable. Spawn point selection must verify traversability."},{"t":"dungeon","f":"Brute-force voxel-based occlusion approximation can provide lighting for particle/voxel systems, but requires all geometry to stay within the voxel grid bounds \u2014 out-of-bounds procedural shapes get clipped, creating visual artifacts."},{"t":"dungeon","f":"Iterated Function Systems (IFS) using randomly generated sets of affine transformations produce unpredictable shapes \u2014 bounding the output within a fixed grid is a key constraint problem when combining proc-gen geometry with grid-based rendering."},{"t":"rendering","f":"WebGL rendering pipeline: vertices (x,y,z coordinates) \u2192 connected into triangles (primitives) \u2192 light source creates shadows/depth \u2192 rasterized from 3D vector to 2D pixel projection"},{"t":"rendering","f":"Shaders are functions that customize the rendering pipeline, written in OpenGL ES Shading Language (not JavaScript), processing vertex or fragment data on the GPU to calculate pixel render data"},{"t":"physics","f":"Rendering at 60fps requires massive linear algebra/matrix multiplication operations that exceed CPU capacity alone, requiring GPU distribution of calculations"},{"t":"rendering","f":"WebGL is based on OpenGL (established 1992), runs hardware-accelerated graphics on client GPU inside an HTML canvas element \u2014 initialized by getting canvas element then calling getWebGLContext()"},{"t":"rendering","f":"3D geometry is built from vertices connected into triangle primitives; rasterization converts these 3D triangles into 2D pixel projections for screen display"},{"t":"rendering","f":"Three.js and Spline are abstraction layers over WebGL that eliminate need to write raw shaders by hand for 3D web experiences"},{"t":"fps","f":"Multiplayer Three.js app architecture: front-end creates player mesh, adds to local scene, then notifies backend; backend broadcasts new player parameters to all other connected front-ends so each client adds remote players to their own scene"},{"t":"fps","f":"Player movement on front-end is handled locally using WASD or arrow keys before any network sync occurs; each client owns and controls only its own player object in the Three.js scene"},{"t":"fps","f":"Remote players are instantiated on each client by receiving parameter sets from the backend and calling the same constructor (e.g. new Hamburger with synced parameters) then adding the result to the local Three.js scene"},{"t":"fps","f":"Position the player's gun on screen so the player can see where they are shooting without needing separate crosshair UI \u2014 gun placement itself should indicate aim direction"},{"t":"fps","f":"Default FPS movement without game feel additions results in a flat glide forward feeling \u2014 camera bob, head bob, and movement sway are necessary to give the player the sensation of having legs"},{"t":"fps","f":"FPS level design should utilize full 3D vertical space rather than flat 2D layouts \u2014 a skybox alone does not make a map three-dimensional if the playable geometry is flat"},{"t":"shooting","f":"Four standard FPS weapon archetypes: normal gun (medium range balanced), sniper rifle (scoped long range), shotgun (close range spread), machine gun (high fire rate with spread) \u2014 each needs distinct effective ranges and spread patterns to feel differentiated"},{"t":"shooting","f":"Machine gun spread pattern must be tuned carefully \u2014 too wide a spread cone makes bullets miss at any practical range, effectively hitting behind the player's intended target"},{"t":"fps","f":"FPS UI should provide all necessary player information (health, ammo, minimap) \u2014 removing UI entirely in favor of 'immersion' removes critical gameplay feedback"},{"t":"physics","f":"Rapier physics engine integrated via @react-three/rapier; wrap Experience component in <Physics> component to enable physics simulation"},{"t":"physics","f":"Stage platform built as low-height cylinder using RigidBody with type='fixed' and explicit cylinder collider (colliders='force') so it blocks objects but doesn't move"},{"t":"interior","f":"MeshReflectorMaterial from drei used to create reflective floor; fog added to blend background objects with the floor for depth effect"},{"t":"interior","f":"GLTF models loaded via useGLTF hook; gltfjsx CLI tool auto-generates React Three Fiber component code from .gltf model files"},{"t":"interior","f":"Text3D component from drei renders 3D text; requires facetype.json font generated from facetype.js; subset characters to reduce file size (20MB full Japanese font reduced to 87KB by including only needed characters)"},{"t":"interior","f":"Zustand used for game state management over React Context (causes re-renders) and Redux (too verbose); game level generator creates array of stages with increasing difficulty by adding more options per stage"},{"t":"interior","f":"Scene lighting uses ambientLight intensity=1 plus directionalLight for shadows; background color set on Canvas component"},{"t":"terrain","f":"Stamp-based terrain sculpting uses a free Unity package called 'Stamp It' where you set stamp height, adjust brush size, and set 'stamp from current height' value to 1 to stack terrain stamps additively"},{"t":"terrain","f":"Procedural Terrain Painter auto-textures terrain using layered rules: higher layers in the stack cover layers below, each layer supports modifiers like 'height' (with max height and max falloff) and 'slope' (to place rock textures on slopes), and multiple modifiers can be combined per layer"},{"t":"water","f":"Unity's built-in Water Surface River object is added via right-click, positioned at terrain center, raised to desired height, rotated and scaled to cover the area, with 'distance wind orientation' controlling river flow direction"},{"t":"terrain","f":"Mass tree placement uses Unity's 'MPL three' option to batch-place vegetation (e.g., 5000 or 10000 models at once) across the entire terrain surface, with tree height min/max controlling model size variation"},{"t":"terrain","f":"Unity Terrain Tools package (installed via Window > Package Manager > Unity Registry) adds 'Spine Details' for grass placement that auto-mixes multiple grass models using 'Target Density' to control frequency of each model type"},{"t":"terrain","f":"Terrain Tools brush mask filters (added via + button) include a 'Layer' filter that restricts detail painting to a specific texture layer with adjustable sharpness, enabling large-area detail placement constrained to specific terrain material zones"},{"t":"terrain","f":"Realistic forests require vegetation of different heights to simulate natural forest layers (canopy, understory, ground cover), combining trees, smaller vegetation, and grass models"},{"t":"interior","f":"In-game phone UI built as UMG Widget Blueprint (WB_Phone) using canvas panels: CP_Phone for outer container, CP_Screen for the screen area, with phone image set to 407x792 pixels matching the 3D phone model dimensions"},{"t":"interior","f":"Phone screen region defined by manually dragging canvas panel anchor points to match the screen portion of the phone image, then child elements use full-size anchors within that constrained CP_Screen canvas"},{"t":"interior","f":"Phone widget centering done via Ctrl+Alt+Shift click on center anchor preset to set pivot to middle, then canvas set to 'desired' size mode instead of 'fill screen' to match phone dimensions"},{"t":"interior","f":"Phone background wallpaper uses image tiling setting on the UMG Image widget to prevent squashing, combined with a background tint color (blue) for visual polish"},{"t":"interior","f":"Doors in hub areas are modeled as visual props that don't lead anywhere \u2014 hallways surrounding the player terminate into void, creating the illusion of a larger space while keeping the playable area minimal."},{"t":"interior","f":"A one-sided piece of geometry is placed directly behind the player's cart to create the illusion that track fades out of existence, hiding the fact that the track model extends far behind the player."},{"t":"interior","f":"Doorway transitions use pitch-black post-processing and a white sphere at the end of the passage; when the player reaches the sphere, the cart immediately stops and the scene cuts to the hub area."},{"t":"interior","f":"Billboards along the intro track are all pre-loaded and visible in the scene but only illuminate as the player passes by them, using lighting activation rather than spawn/load triggers."},{"t":"interior","f":"The prize crane mechanism teleports back to its original suspended position behind a back wall after leaving the player's sight, rather than animating a return path."},{"t":"interior","f":"Room exteriors are covered in a default/placeholder texture since the player is never meant to see them; only interior-facing surfaces receive final art."},{"t":"interior","f":"Hidden objects placed out of bounds include a disc-shaped flashing light and an 'end Showtime' button positioned to the right of the stage area, used as developer control assets."},{"t":"interior","f":"A 360\u00b0 immersive room requires multiple projectors, computers, and projection mapping software to create seamless interior environments"},{"t":"interior","f":"Remote debugging of a multi-projector immersive room setup can be completed within 30 minutes when using projection mapping software"},{"t":"interior","f":"Adding sensors to an immersive projection room enables interaction with virtual content, allowing users to trigger and manipulate scene elements"},{"t":"vehicles","f":"Car movement and logic built iteratively in three.js with checkpoints and booster sections as core game mechanics"},{"t":"city","f":"Environment blocked out first in Blender focusing on track layout and feel before adding detail"},{"t":"rendering","f":"Lights set up in Blender and baked into lightmaps for optimal web performance rather than using real-time lighting"},{"t":"rendering","f":"Low-poly assets modeled and textured in Blender to add detail while keeping geometry count browser-friendly"},{"t":"vehicles","f":"Checkpoints and booster sections implemented as track mechanics to structure race progression and add speed variation"},{"t":"npc","f":"City Sample Crowds in UE 5.5 requires enabling the MassAI (MCrow) plugin, then adding the City Sample Crowds content package (select 5.3 version as no 5.5-specific update exists)"},{"t":"npc","f":"BP_CrowdCharacter blueprint must be reparented from SkeletalMeshActor to Character class, then all 5 SkeletonMeshComponent references must be replaced with the new mesh component"},{"t":"npc","f":"MassAgent component requires 3 entity config traits: AgentCapsuleCollisionSync (set to ActorToMass with ZSync transform deselected), AgentMovement (MassToActor), and AgentOrientationZ (MassToActor)"},{"t":"npc","f":"UE 5.5 introduces a new error in the GetSafeCopy function of BP_CrowdCharacter; fix by clicking MakeArray, deleting the empty array element, and recompiling"},{"t":"city","f":"ZoneGraph system uses ZoneShapes placed in levels with Lane Profiles containing forward and backward lanes (set width to 100); must enable Show > Developer > ZoneGraph in viewport to visualize shapes"},{"t":"npc","f":"ZoneShape Lane Profiles require custom tags (e.g., 'Peds') to be created and assigned, with the default tag deselected, to properly route crowd agents"},{"t":"npc","f":"Skeletal mesh components must be moved one-by-one into the Mesh component hierarchy and positioned inside the capsule collider; moving all at once can crash the editor"},{"t":"city","f":"Unity terrain detail distance must be increased (e.g., 250) to render grass/details visible from the player's position; default is too low for open worlds"},{"t":"city","f":"Fog density of approximately 0.0045 with color sampled from the low horizon of the skybox creates a cohesive fade that hides terrain detail pop-in boundaries"},{"t":"city","f":"Unity Mass Place Trees feature can batch-place 15,000 trees across an entire terrain in one operation, but tree distance in terrain settings must be increased to render distant trees"},{"t":"city","f":"Terrain brush size of ~400 gives coarse landscape height passes, then reducing to ~200 adds finer terrain detail; use a brush with noise for natural-looking elevation"},{"t":"city","f":"For grass detail textures, sample the healthy color from lighter parts of the base ground texture and the dry color from darker parts using the eyedropper to maintain color cohesion"},{"t":"city","f":"A cohesive open world scene requires color-sampling consistency: skybox horizon color for fog, base texture colors for grass healthy/dry tints, and tree prefab materials matching the grass environment"},{"t":"npc","f":"Replica AI NPC demo requires a 28 GB download, runs via a local setup/install process, and processes voice input with variable response latency \u2014 sometimes noticeably longer than real-time conversational pace"},{"t":"npc","f":"AI NPCs maintain per-character personality and emotional state: different NPCs respond with distinct attitudes (hostile, dismissive, helpful) and can escalate or de-escalate based on player tone and conversation history within a session"},{"t":"npc","f":"AI NPCs can process contextual environmental queries (e.g., weather, directions to landmarks like a park) and generate spatially-aware responses such as 'go straight down the street and take a left at the next corner'"},{"t":"city","f":"The demo city environment includes sidewalks, streets with vehicle traffic (including box trucks), stairs, and pedestrian NPCs walking routes \u2014 but has visible boundary limits referred to as 'the Matrix wall'"},{"t":"vehicles","f":"The demo features AI-driven traffic with vehicles like box trucks navigating city streets, and NPCs contextually reference the traffic conditions (e.g., 'the traffic's ridiculous') when prompted"},{"t":"npc","f":"Voice-to-voice NPC interaction uses a pipeline of speech recognition \u2192 AI text generation \u2192 text-to-speech, with the latency gap visible between player speech ending and NPC audio response beginning"},{"t":"npc","f":"The Unrecord game (police game) shares assets with the Replica demo (e.g., the same box truck model appears in both), indicating asset reuse across AI NPC tech demos and game prototypes"},{"t":"shooting","f":"Bullet movement uses rotation basis multiplied by speed constant (set to 40) in the process function to move projectiles forward along their local negative Z axis"},{"t":"shooting","f":"Shoot animation length is 0.1 seconds (a tenth of a second) with snapping set to 100, using 3 keyframes: original position, gun pulled back, return to original position \u2014 only the middle keyframe position changes"},{"t":"shooting","f":"Fire rate control checks if shoot animation is NOT currently playing before allowing another shot \u2014 if animation finished or button just pressed, play shoot animation again"},{"t":"shooting","f":"Bullet mesh is a BoxMesh with X and Y dimensions set to 0.05, with emission color at strength 5 for a glowing projectile effect"},{"t":"shooting","f":"Gun barrel spawn point uses a RayCast3D with target_position set to negative Z (0, 0, -1) since negative Z is the forward direction in Godot's coordinate system"},{"t":"shooting","f":"Bullet collision detection uses a RayCast3D attached to the bullet with length slightly exceeding the mesh bounds, pointing in negative Z direction"},{"t":"fps","f":"Gun is parented as child of the camera node, positioned using camera preview checkbox to see first-person view without running the game; shadow casting is disabled on gun mesh via cast_shadow setting in geometry section"},{"t":"shooting","f":"Hitscan bullets have zero travel time and hit whatever is at the crosshair center instantly when the trigger is pulled. Projectile bullets send a physical in-game object with real travel time requiring the player to lead shots on moving targets."},{"t":"shooting","f":"Bullets can originate from the center of the camera (between the eyes) or from the gun barrel. Camera-origin means the bullet naturally hits where the crosshair points. Games like Overwatch, Apex Legends, and CS:GO shoot from the camera/eyes."},{"t":"shooting","f":"Camera-origin shooting enables 'head glitching' where players shoot from behind cover as long as their head is unobstructed. The fix is to move the camera down to about chest height so the view is obstructed when behind cover."},{"t":"shooting","f":"For camera-origin projectiles, a fake cosmetic bullet is fired from the gun barrel for visual effect while the real invisible projectile originates from the camera center. In Overwatch, projectiles near wall edges pass through visually but the real hitbox projectile never collides with the wall."},{"t":"shooting","f":"Barrel-origin shooting (used by PUBG, Escape from Tarkov, TF2 Soldier's rocket launcher) causes bullets to hit slightly off-center from the crosshair unless the developer compensates. Players must offset aim when hip-firing and watch for walls blocking the barrel's line of fire."},{"t":"shooting","f":"With barrel-origin bullets, enemies who get between the player and the gun barrel tip cannot be hit even if the crosshair is on them, because guns have physical length. Games handle this by pulling the gun model back near objects or disabling shooting at very close range."},{"t":"shooting","f":"A hybrid bullet type exists where bullets are hitscan up to a certain distance and become projectiles beyond that threshold. Used in some Halo games and Insurgency: Sandstorm to give close-range weapons like SMGs immediacy while limiting long-range sniper effectiveness."},{"t":"recoil","f":"Prodeus uses per-shot screen shake (screen vibration on every gunshot) as a recoil-feel mechanic, giving visceral feedback without complex recoil patterns"},{"t":"ammo","f":"Ultrakill replaces traditional ammo/health pickups with a blood-as-fuel mechanic where killing enemies at close range refills health, encouraging aggressive play"},{"t":"ammo","f":"Prodeus horror mods use severely limited ammo pools combined with restricted lighting to shift the genre from action shooter to survival horror within the same engine"},{"t":"hitscan","f":"Ultrakill features a fist-parry mechanic that reflects enemy bullets back, implying projectile-based (non-hitscan) bullets that can be intercepted and redirected mid-flight"},{"t":"impact_force","f":"Prodeus enemies use high-pressure blood-explosion death effects (described as 'blood pinatas') with gore that coats the player's gun model and environment walls"},{"t":"shooting","f":"Ultrakill implements a coin-toss trick-shot system where firing a bullet at a thrown coin redirects it toward enemies, combining projectile physics with precision timing"},{"t":"weapon_setup","f":"To attach a weapon model in Unity FPS, drag the model inside the player hierarchy alongside the dummy weapon, then align its transform position to match the dummy weapon's position."},{"t":"weapon_setup","f":"After importing a weapon prefab, right-click and select 'Prefab > Unpack Completely' to break the prefab link so individual parts can be freely modified."},{"t":"weapon_setup","f":"Weapon model scale often needs manual adjustment after import; e.g. a pistol prefab was scaled to 2x its default size to look correct in first-person view."},{"t":"rendering","f":"Pink/magenta materials on imported weapon models indicate a shader mismatch; fix by selecting all materials then using Edit > Rendering > Materials > Convert Selected Built-in Materials to URP."},{"t":"shooting","f":"Camera raycast aiming works by casting a ray from screen center, then faking the bullet trail from the gun barrel to the hit point; trails play fast enough that imperfect angles are unnoticeable"},{"t":"shooting","f":"Camera raycast method causes bullet trails to clip through walls near the gun because the ray originates from the camera while the trail renders from the gun barrel, creating a perspective mismatch"},{"t":"shooting","f":"Third-person shooters exacerbate the camera-vs-gun offset problem because the camera is significantly farther from the gun than in first person, and objects can pass between camera and player causing backward shots"},{"t":"shooting","f":"Barrel-origin shooting (raycast or projectile from gun muzzle) is the most realistic but makes crosshair placement difficult because gun model sway causes the aim point to shift constantly"},{"t":"shooting","f":"A hybrid aiming method uses a camera raycast to find a world-space target point, then aims the gun barrel toward that point and fires the projectile from the gun, combining camera-based targeting with barrel-origin bullets"},{"t":"shooting","f":"Three standard aiming implementations: (1) camera raycast with faked bullet trail from gun, (2) direct barrel-origin raycast/projectile, (3) hybrid where gun aims at camera raycast hit point then fires from barrel"},{"t":"tps","f":"Camera follow uses a CameraHolder empty object with child camera; a CamPos transform (Y=2.6) inside the player is tracked each Update via transform.position = camPos.position for direct position lock"},{"t":"tps","f":"Mouse look uses Input.GetAxisRaw MouseX/MouseY multiplied by sensitivity (100) and 0.01f; vertical rotation (X axis) is clamped to -90..90 degrees via Mathf.Clamp"},{"t":"tps","f":"Orientation is a separate empty child object inside the player whose rotation is set to Quaternion.Euler(0, yRotation, 0); camera transform gets Quaternion.Euler(xRotation, yRotation, 0) \u2014 decoupling body yaw from camera pitch"},{"t":"tps","f":"Player movement direction is calculated as orientation.forward * yInput + orientation.right * xInput, then force is applied to Rigidbody in FixedUpdate with moveSpeed=10"},{"t":"tps","f":"Rigidbody is configured with Interpolate=Interpolate and CollisionDetection=ContinuousDynamic; rb.freezeRotation=true is set in Start to prevent physics-driven rotation"},{"t":"tps","f":"Cursor is locked and hidden at Start via Cursor.lockState=CursorLockMode.Locked and Cursor.visible=false"},{"t":"tps","f":"Right stick rotates camera up/down and around the character providing full orbit control in third person view"},{"t":"tps","f":"Left stick analog sensitivity controls locomotion blend: soft press triggers walk animation, full tilt triggers sprint animation"},{"t":"tps","f":"Ground detection uses raycasting to know when the character has hit the ground for ground checks and landing animations"},{"t":"tps","f":"Unity new Input System package required for simultaneous mouse/keyboard and controller support in third person controller"},{"t":"tps","f":"Standard/built-in pipeline materials convert to URP via Window > Rendering > Render Pipeline Converter using upgrade materials then initialize and install"},{"t":"tps","f":"Character materials use Universal Render Pipeline Lit shader with albedo base map, normal map, and metallic smoothness map slots"},{"t":"tps","f":"Unity Starter Assets Third Person Controller uses a CineMachine camera (player follow camera) for third person camera control, separate from the main camera"},{"t":"tps","f":"The Starter Assets third person controller prefab must be unpacked completely (right-click > unpack prefab completely) before customization, and the scene's existing main camera must be removed first"},{"t":"tps","f":"Unity third person controller supports WASD movement, sprint, jump with sound effects, and CineMachine-driven camera orbit control out of the box with zero additional scripting"},{"t":"tps","f":"To retarget a Mixamo or third-party character mesh to Unity's third person controller, set the imported FBX model rig type to Humanoid and hit Apply, which maps the skeleton to Unity's humanoid avatar system"},{"t":"tps","f":"When swapping character meshes, the new mesh is placed inside the PlayerArmature > Root > Geometry hierarchy, and the transform must be reset (right-click transform > Reset) to align it to the correct position"},{"t":"tps","f":"Mixamo FBX exports for Unity should use FBX for Unity format with the character kept in T-pose (original position) to ensure correct animation retargeting"},{"t":"tps","f":"In Unreal Engine, skeletal mesh components have 'Only Owner See' and 'Owner No See' boolean properties under Rendering > Advanced that control per-player mesh visibility in multiplayer."},{"t":"tps","f":"For the first-person mesh: set 'Only Owner See' = true and 'Owner No See' = false. For the third-person mesh: set 'Only Owner See' = false and 'Owner No See' = true."},{"t":"tps","f":"With Owner No See enabled on the third-person mesh, the owning player cannot see their own third-person shadow or legs when looking down, confirming the mesh is fully hidden locally."},{"t":"tps","f":"In a Listen Server setup with two players, each player's pawn has both a first-person skeletal mesh (FPS arms/weapon) and a separate third-person skeletal mesh (full body) attached simultaneously."},{"t":"tps","f":"Using F8 (Eject/Possess) in editor reveals both the first-person and third-person meshes simultaneously since camera ownership rules no longer apply to the detached spectator view."},{"t":"tps","f":"Cinemachine FreeLook camera uses follow and lookAt targets set to the player character to create an orbiting third person camera"},{"t":"tps","f":"FreeLook camera X-axis speed controls horizontal orbit rate (default was high, reduced to 100 for smoother rotation) and Y-axis speed controls vertical look (reduced to 4 for smoother vertical panning)"},{"t":"tps","f":"Cinemachine FreeLook camera is preferred over vcam for third person because it provides full orbital mouse-driven rotation around the character on both X and Y axes"},{"t":"tps","f":"Camera smoothing in third person is achieved by tuning X-axis and Y-axis speed values lower \u2014 reducing X-axis from default to ~100 and Y-axis to ~4 eliminates jerky rotation"},{"t":"tps","f":"Third person character velocity can be adjusted independently from camera speed to control movement feel without affecting camera orbit behavior"},{"t":"tps","f":"Use ForceMode.VelocityChange when adding force to a rigid body player controller \u2014 this ensures velocity changes are not affected by the rigid body's mass or the physics simulation step length"},{"t":"tps","f":"Apply high drag only while the player is grounded and low drag while airborne \u2014 constant high drag causes floating/gliding when walking off edges"},{"t":"tps","f":"Never directly set rigid body velocity every physics frame \u2014 it breaks the physics simulation; use AddForce instead as recommended by Unity documentation"},{"t":"tps","f":"Ground checking with a single raycast is inaccurate \u2014 use a sphere cast or OnCollisionEnter, then verify the hit is actual ground by checking the slope angle (angle between player down vector and surface normal) against a threshold"},{"t":"tps","f":"Wall collisions can falsely register as ground \u2014 fix by assigning ground objects to a dedicated physics layer or by comparing the slope angle between the player's down vector and the contact normal"},{"t":"tps","f":"For character controller + physics interaction, apply a force at each contact point in the direction of the surface normal on every rigid body the controller touches"},{"t":"cannon.js_vehicle_physics","f":"Cannon.js physics engine combined with React Three Fiber enables car physics with angular velocity control while airborne, allowing flip tricks off ramps"},{"t":"react_three_fiber_scene_setup","f":"All Three.js scripts must be wrapped under the Canvas component because React Three Fiber hooks cannot be used outside of Canvas"},{"t":"3d_environment_map","f":"A 3D scene background can be created using an environment map loaded via the Environment component, producing a blurred background that supports orbit controls"},{"t":"third_person_camera","f":"A toggleable third-person camera view can be implemented alongside orbit controls for vehicle-based gameplay in React Three Fiber"},{"t":"physics_colliders","f":"Scene elements like trees, signs, and ramps can act as physics colliders in cannon.js, enabling realistic collision responses for vehicles"},{"t":"react_three_fiber_dependencies","f":"Core dependency stack for a 3D physics game: three.js, @react-three/fiber, @react-three/drei (utility functions), and @react-three/cannon (physics) \u2014 pin exact versions for stability"},{"t":"hitscan","f":"Hitscan weapons perform instant ray checks from crosshair to target \u2014 if the crosshair is on the enemy at fire time, it registers a hit with zero travel time, making accuracy a pure aim check."},{"t":"hitscan_ai","f":"AI bots with hitscan weapons can theoretically hit 100% of shots since there is no projectile to dodge \u2014 accuracy must be artificially limited by programming inaccuracy or the bot effectively becomes unavoidable damage-over-time."},{"t":"hitscan_counterplay","f":"Movement speed can serve as implicit hitscan counterplay \u2014 bots are typically programmed to be less accurate against faster-moving targets, letting games like Titanfall 2 use high-speed movement to simulate the dodge dynamics of projectile weapons."},{"t":"bullet_spread","f":"Counter-Strike adds depth to hitscan by requiring players to learn per-weapon spray patterns, control fire rate to allow aim reset, and stand still while shooting \u2014 turning accuracy into a technical skill layer on top of basic aim."},{"t":"projectile_counterplay","f":"Projectile weapons have inherent counterplay because shots are visible and have travel time \u2014 players can dodge by moving radically or increasing distance, which increases the lead prediction required by the shooter."},{"t":"hitscan_design","f":"FEAR makes hitscan work by having enemy soldiers vocally narrate their actions (flanking, grenading, etc.), turning cover-based hitscan counterplay from passive waiting into active tactical decision-making."},{"t":"shooting","f":"Hitscan shooting uses Physics.Raycast originating from the camera position in the forward direction; if nothing is hit, no action is taken"},{"t":"shooting","f":"A gun script requires configurable public floats: damage (default 10) and range (default 100 units)"},{"t":"shooting","f":"Input.GetButtonDown('Fire1') maps to the left mouse button by default in Unity and is used to trigger the shoot function"},{"t":"shooting","f":"RaycastHit stores information about what the ray collided with, enabling damage application and impact effects"},{"t":"shooting","f":"Gun graphics should be parented to the main camera, and the camera's near clipping plane must be decreased to prevent the gun model from being clipped"},{"t":"shooting","f":"Raycast hitscan guns can apply an impact force to physics objects on hit, in addition to damage and visual effects like muzzle flash and impact particles"},{"t":"shooting","f":"Hitscan guns use Physics.Raycast instead of spawning a rigidbody bullet game object, determining hits instantly in one frame"},{"t":"shooting","f":"Hitscan bullet trails use a TrailRenderer that goes from the shot origin point to the raycast hit point, with an impact particle system spawned at the hit location"},{"t":"shooting","f":"Hitscan shooting requires only 2 scripts: a Gun script (attached to the weapon game object) and a PlayerAction script (attached to the player capsule) that calls gun.shoot()"},{"t":"shooting","f":"Unity's new Input System uses Send Messages behavior to call an OnShoot method on all scripts attached to the game object with PlayerInput, triggered by a custom 'shoot' action bound to left mouse button"},{"t":"shooting","f":"The Gun reference in PlayerAction is a private serialized field ([SerializeField] private Gun gun) so it can be assigned in the Unity Inspector rather than hardcoded"},{"t":"camera","f":"Camera follow is implemented by creating a 'camera holder' empty object, making the camera a child of it, then in Update setting transform.position = camPos.position where camPos is a transform reference point parented to the player at Y offset 2.6"},{"t":"FPS","f":"First-person mouse look uses two floats x and y, accumulating input via y += Input.GetAxisRaw('Mouse X') * sensX * 0.01f and x -= Input.GetAxisRaw('Mouse Y') * sensY * 0.01f, then clamping x with Mathf.Clamp(x, -90, 90)"},{"t":"FPS","f":"Camera rotation is split: orientation.rotation = Quaternion.Euler(0, y, 0) for horizontal yaw on a separate orientation object, and transform.rotation = Quaternion.Euler(x, y, 0) for the camera itself combining pitch and yaw"},{"t":"FPS","f":"Movement direction is calculated as Vector3 moveDirection = orientation.forward * yInput + orientation.right * xInput, then force is applied to the Rigidbody so movement aligns with camera yaw without pitch influence"},{"t":"FPS","f":"Rigidbody is configured with Interpolate set to 'Interpolate' and Collision Detection set to 'Continuous Dynamic', with rb.freezeRotation = true in Start to prevent physics-driven rotations"},{"t":"camera","f":"Camera follow target (camPos) is placed as a child of the player object at local position Y = 2.6, representing approximate eye height above the player capsule origin"},{"t":"FPS","f":"Mouse sensitivity values are set to approximately 100 for both X and Y axes, multiplied by 0.01f in code (effective multiplier 1.0), with cursor locked via Cursor.lockState = CursorLockMode.Locked and Cursor.visible = false"},{"t":"camera","f":"Spring arm (camera boom) target arm length set to 200-250 units for third-person follow camera; socket offset Y = 35; target offset Z = 60"},{"t":"camera","f":"Custom event 'MoveCamera' takes two float inputs: TargetArmLength and SocketYOffset, with variables LastSocketY and LastArmLength storing current values before interpolation"},{"t":"camera","f":"Camera boom current values cached by reading GetSocketOffset.Y into LastSocketY and GetTargetArmLength into LastArmLength before any transition begins"},{"t":"camera","f":"Timeline node 'CameraFloat' with length 1 second drives the interpolation; keyframes at (0, 0) and (0.7, 1) with first keyframe set to Auto tangent for smooth easing"},{"t":"camera","f":"Lerp node interpolates TargetArmLength: A = LastArmLength, B = target input value, Alpha = timeline float output; result fed into SetTargetArmLength on camera boom each tick (Update pin)"},{"t":"camera","f":"Second lerp node interpolates SocketOffset.Y: A = LastSocketY, B = target SocketYOffset input, Alpha = same timeline float; result fed into SetSocketOffset split Y pin"},{"t":"camera","f":"Sprint triggers MoveCamera with extended arm length (e.g. 250) to pull camera further back; returning to walk resets to default values via StopCamera and ResetCamera custom events on timeline Stop/NewTime pins"},{"t":"collision","f":"Door interaction box collision dimensions: X scale 2.5, Y scale 1.75, Z scale 3.45 \u2014 sized to encompass both the player character and the door swing radius."},{"t":"collision","f":"Door system uses a scene component called 'door open location' as a child of the door mesh to define the target transform for open/partial-open states, separate from the collision volume."},{"t":"camera","f":"Resident Evil door transitions use a three-state enumeration cycle: Closed \u2192 Partially Open \u2192 Open, repeating in order, to control door animation and camera behavior during traversal."},{"t":"camera","f":"Spring arm (camera boom) socket offset of X:0, Y:60, Z:60 with target arm length 120 creates a dead-space style over-the-shoulder third-person camera"},{"t":"camera","f":"Store the starting socket offset in a variable at BeginPlay so aim-to-unaim transitions can restore the original camera position instead of resetting to 0,0,0"},{"t":"camera","f":"Set ViewPitchMax to 40 degrees via GetPlayerCameraManager to prevent extreme vertical camera rotation in third-person mode"},{"t":"camera","f":"Camera boom socket offset X controls forward/back, Y controls left/right shoulder offset, Z controls height offset relative to the follow target"},{"t":"camera","f":"Over-the-shoulder aim mode transitions involve interpolating the socket offset from a wider TPS position to a tighter aim position, triggered by right mouse button input"},{"t":"camera","f":"Camera setup logic should be encapsulated in a dedicated function (e.g. SetUpCamera) called once from BeginPlay to cache initial spring arm values before any runtime transitions modify them"},{"t":"camera","f":"For true first person in UE5, delete the spring arm component and parent the camera directly to the skeletal mesh component, then set the parent socket to 'head'"},{"t":"camera","f":"Camera transform for true first person on helmeted character: location offset (10, 20, 290) and rotation 90 degrees to align forward with character facing direction"},{"t":"camera","f":"Camera must be rotated 90 degrees on one axis after parenting to head socket to correct the default orientation so the view faces forward"},{"t":"camera","f":"For characters with large head geometry (helmets), push the camera location further forward from the head socket to prevent the mesh clipping into view"},{"t":"camera","f":"Head-parented camera inherits all skeletal animation motion, causing significant wobble during combat animations designed for third person"},{"t":"FPS TPS","f":"Converting TPS to true FPS requires duplicating the entire player character blueprint hierarchy (base player, full player, final player) and reparenting each layer to maintain framework functionality"},{"t":"FPS TPS","f":"True first person (camera on head bone) lets the player see their full body when looking down, unlike viewport-only first person which hides the body"},{"t":"collision","f":"Use sphere cast instead of single raycast for ground checking \u2014 a raycast will falsely report the player is airborne when standing on an edge, while a sphere cast covers more area beneath the collider"},{"t":"collision","f":"Make the sphere cast radius slightly smaller than the character collider radius so it won't register wall contacts as ground contacts, though this can introduce other edge cases"},{"t":"collision","f":"Validate ground contacts by checking slope angle: compute the angle between the player's down vector and the surface normal vector, and only register as ground if the angle is below a threshold"},{"t":"collision","f":"For character controller physics interaction with rigidbodies, apply a force at each contact point in the direction of the surface normal for every contact the character controller makes"},{"t":"collision","f":"Use ForceMode.VelocityChange when adding movement force to a rigidbody player controller \u2014 this makes velocity changes independent of rigidbody mass and physics timestep length"},{"t":"collision","f":"Apply high drag on a rigidbody controller only while grounded and set drag much lower when airborne \u2014 grounded-only high drag fixes slipperiness, while low air drag prevents floating/gliding when walking off edges"},{"t":"collision","f":"On slopes, project the movement force vector to be parallel to the ground surface using the ground normal, and add an upward counter-force to counteract gravity \u2014 otherwise the player moves slower uphill, faster downhill, and slides when stationary"},{"t":"buoyancy","f":"Buoyancy force is calculated as Vector3.up multiplied by floatingPower multiplied by the difference between water height and rigidbody Y position, so deeper submersion produces stronger upward force"},{"t":"buoyancy","f":"ForceMode.Force is used when applying the upward buoyancy force to the rigidbody, which accounts for mass and applies force over time rather than as an impulse"},{"t":"buoyancy","f":"Underwater drag values of 3 (linear) and 1 (angular) versus air drag values of 0 (linear) and 0.05 (angular) are used, switching between them based on whether the object is submerged"},{"t":"buoyancy","f":"A waterHeight float defines the Y-level of the water plane, and the difference between waterHeight and the rigidbody's Y position determines submersion depth and force magnitude"},{"t":"buoyancy","f":"The script uses RequireComponent(Rigidbody) attribute and runs buoyancy logic in FixedUpdate since it is physics-based, with a boolean tracking whether the object is currently underwater"},{"t":"buoyancy","f":"The water surface is a plane with its collider removed, serving only as a visual reference while the waterHeight float handles the actual physics boundary"},{"t":"water","f":"Water material controls normal map, scattering, color tints, reflections, foam settings, and SSS (subsurface scattering) tint to adjust overall water appearance"},{"t":"water","f":"Foam generation is driven by shallow depth \u2014 shallower areas produce more foam, with adjustable foam strength that updates in real-time during rendering"},{"t":"water","f":"Wave animation uses an FFT (Fast Fourier Transform) shape component on a separate game object to generate animated waves"},{"t":"water","f":"Water system requires linear color space (not gamma) set in Project Settings > Player > Other Settings for correct rendering"},{"t":"water","f":"Ocean rendering uses a LOD system with underwater support, surface clipping, acoustic simulation, and scattering \u2014 all as modular add-on components"},{"t":"water","f":"Water system supports physics interaction allowing objects to be affected by water buoyancy and wave forces"},{"t":"water","f":"Gerstner waves combine multiple sine waves to create complex ocean surfaces; more waves increase computational cost proportionally."},{"t":"water","f":"Ocean mesh is a plane with LOD that gradually reduces detail from center outward; since waves are world-space, the mesh moves with the player to simulate an infinite ocean."},{"t":"water","f":"Distant waves use scrolling normal map textures on a completely flat surface instead of Gerstner displacement, saving GPU cost since the player never gets close."},{"t":"water","f":"Ocean height data is rendered to a Render Target so any object in the world can cheaply sample wave height instead of recalculating Gerstner equations per-object; limitation is no rotation data is available."},{"t":"water","f":"Surface foam is added during stormy weather by increasing wave height and sharpness, combined with Niagara particle splashes spawned on wave peaks via a scratch pad module that samples the wave render target and destroys particles on low waves."},{"t":"water","f":"Fake god rays are created in a fog material by stretching a noise texture in the light direction to brighten the fog, faded out over depth; volumetric shadow methods and shadow-casting planes were rejected due to visual artifacts."},{"t":"water_volume_setup","f":"ACF (Advanced Character Framework) uses a Physics Volume actor to define swimmable water areas. Place the volume to cover the water region and enable the 'Water Volume' flag so the framework auto-detects swim state."},{"t":"swim_trigger","f":"Swimming is triggered by character overlap with the Physics Volume; exiting the volume immediately reverts the character to ground locomotion (walk/run blend space)."},{"t":"water_surface_alignment","f":"The top face of the Physics Volume should be aligned with the water surface mesh so the swim-to-walk transition matches the visible waterline and avoids awkward blending near the shore."},{"t":"swim_blend_space","f":"ACF uses a blend space for swim animations that activates automatically when the Water Volume flag is enabled on the physics volume \u2014 no additional animation blueprint wiring is required."},{"t":"water_color_absorption","f":"Water color is implemented via light absorption formula: absorption_coefficient = percentage of light absorbed, using formula where alpha is absorption coefficient, a is percentage absorbed, x is material thickness. The absorption value is subtracted from scene color rather than multiplied."},{"t":"water_transparency","f":"Water transparency uses the Scene Color node (screen color buffer before water plane renders) instead of alpha output. The shader must be marked as transparent to access pre-rendered screen content."},{"t":"water_depth_fade","f":"Water color changes based on depth: deeper water absorbs more color. Depth is calculated from camera position using the Scene Depth node (camera depth buffer before object renders), determining how much water the viewer is looking through."},{"t":"water_absorption_color_inversion","f":"To select a desired water color instead of an absorption color, use one_minus(waterColor) to derive the absorption color. This inverts the target color so the absorption process yields the intended final water color."},{"t":"water_shader_components","f":"A complete water shader consists of: transparency, color absorption, caustics, reflectiveness, aeration (foam/bubbles), and aeration movement. Each can be implemented as separate modules."},{"t":"water_absorption_formula","f":"Absorption formula nodes: absorption_coefficient controls how far light travels through material before fully absorbed, varies per wavelength and material. Result is multiplied by absorption color to get percentage of color visible, then subtracted from scene color."},{"t":"HDRP water setup","f":"Unity HDRP water system requires version 16+ of HDRP package and Unity 2023.2+; water surfaces are added via hierarchy right-click > Water menu with options for ocean/sea/lake, pool, and river"},{"t":"HDRP water rendering pipeline","f":"Full water rendering requires enabling multiple pipeline features: water simulation, deformation, water foam, script interactions, surface decals, screen space reflections, and transparent screen reflections"},{"t":"HDRP water surface types","f":"The HDRP water system provides distinct surface types: Ocean/Sea/Lake for large bodies, Pool for contained water, and River for flowing water, plus auxiliary tools including excluder, deformer, and foam generator"},{"t":"HDRP water visual features","f":"The water system supports waves, ripples, foam, underwater caustics, refractions, reflections, and deformation simulation as built-in features"},{"t":"HDRP water samples","f":"Unity provides importable water sample scenes via Package Manager > HDRP > Samples > Water Samples, including an Island scene pre-configured with correct water rendering settings"},{"t":"HDRP water deformation","f":"Water deformation is a separate render pipeline feature that must be enabled independently from base water rendering in the HDRP quality asset settings"},{"t":"water","f":"Stylized Water for URP requires Unity 2019.3.9+ and supports buoyancy, waves, foam, refraction, planar reflections, and custom lighting"},{"t":"water","f":"Water depth rendering uses shallow color near objects and deep color at edges, with configurable horizon settings and shore edge blending"},{"t":"water","f":"Surface foam uses texture-based alpha cutoff, distortion amount, configurable scale, direction, and speed for both primary and secondary foam layers"},{"t":"water","f":"Intersection effects detect world objects intersecting water and apply configurable direction, scale, and blending at contact points"},{"t":"water","f":"Asset includes specialized prefabs for beach cascading water, buoyancy floating objects, object interaction with planar reflections, and stylized game water"},{"t":"water","f":"Foam shadows can be enabled separately with configurable strength, intersection amount, and foam effect intensity"},{"t":"proc-gen","f":"Unconstrained random generation produces white-noise output \u2014 blocks everywhere with no terrain contour; constraints must enforce dirt-on-surface, no sky blocks, consistent terrain flow, and tree self-similarity to produce playable worlds."},{"t":"proc-gen","f":"Even with constraints, undesirable edge cases slip through \u2014 ranging from funny quirks to full unplayability (e.g., Terraria spawning a player surrounded by impassable stone). At 1% failure rate with millions of players, thousands get broken worlds."},{"t":"proc-gen","f":"Procedural generation is not inherently random \u2014 results can be deterministic (same seed = same output). Randomness is opted into specifically to produce unpredictable variety; without that goal, manual authoring is preferred."},{"t":"proc-gen","f":"The core engineering tradeoff: enough variance to keep gameplay unique and replayable vs. enough constraints to prevent unplayable degenerate cases. Tightening constraints reduces variety; loosening them increases failure rate."},{"t":"proc-gen","f":"High-fidelity games (e.g., God of War) still use procedural generation during development for element placement like foliage positions, but artists make the final design decisions \u2014 a hybrid approach that avoids runtime generation risks."},{"t":"proc-gen","f":"Iterated function systems (IFS) using randomly generated sets of affine transformations can drive particle system visualizations, producing attractor patterns useful for procedural effects and lighting."},{"t":"environment_design","f":"Complex dense environments like Elden Ring's Lindell Capital gate use a strategy of overwhelming scale with soaring towers and intricate filigree detail to convey power and royalty \u2014 the visual density is intentional design language, not random placement."},{"t":"environment_design","f":"Every placement of rocks, broken churches, and cave entrances in Elden Ring is deliberately considered to weave storytelling into the environment geometry itself."},{"t":"workflow","f":"Step 1 of environment recreation in Unreal Engine is gathering reference (images, videos, on-location photos, sketches) using a tool called PureRef to dissect the logic and visual structure before any 3D work begins."},{"t":"environment_design","f":"Large-scale fantasy environments achieve depth and impact through layered visual complexity \u2014 dense intricate surface detail (filigree) combined with macro-scale architectural forms (towers, gates) creates the 'larger than life' effect."},{"t":"marching_cubes","f":"8 corner points per cube, each with a noise value; values above 0 = air/open space, below 0 = rock/solid. 256 possible configurations but only 15 unique cases (rest are symmetries). Surfaces constructed from triangles by connecting edges in groups of 3."},{"t":"density_field","f":"Terrain stored as a 3D texture of scalar values. Zero crossing defines the surface boundary. Negative values = inside solid, positive = open air. Slicing the 3D texture shows lighter regions (outside) and black regions (below surface) with a red boundary line at value 0."},{"t":"marching_cubes_gpu","f":"Core algorithm written in HLSL to process many cubes in parallel on the GPU. Per cube: calculate 8 corner coordinates, look up their density values, determine which of 256 configurations applies via a precomputed triangle table, then find which edges the surface passes through and connect vertices in groups of 3 to form triangles."},{"t":"terraforming_caves","f":"Single-heightmap planets cannot represent caves, tunnels, or overhangs because each point maps to only one height value. A volumetric density field (3D grid of air/rock values) solves this, enabling carving of arbitrary underground geometry."},{"t":"marching_cubes_lookup","f":"A giant precomputed lookup table maps each of the 256 cube configurations to triangle edge connections. Two small arrays map each edge index to its two endpoint corner indices. Vertex placement along each edge defaults to the midpoint for simplicity."},{"t":"planet_noise","f":"Planet terrain generated by starting with a sphere, sampling a 3D noise function at each surface point, and displacing vertices inward/outward based on the noise value. Mixing and layering different noise functions with different equations produces varied terrain."},{"t":"underground_tunnel","f":"Sewer tunnel used as connection path between two building basements; requires blocking out geometry for arch-shaped ceiling and snapping vertices to grid for proper alignment"},{"t":"environmental_storytelling","f":"Sand pouring through drainage grates serves dual purpose: visual storytelling element showing surface proximity and gameplay mechanic providing player entry path into underground space"},{"t":"lighting_underground","f":"Underground spaces require blocking out additional light to sell the illusion of depth; too much ambient light leaking into basement/tunnel areas breaks the underground feel"},{"t":"modular_level_design","f":"Plank boards placed over openings need careful overlap management to avoid z-fighting; thicker board geometry matches concept art and helps sell light occlusion at surface boundaries"},{"t":"tunnel_geometry","f":"Arch-shaped tunnel ceilings require additional subdivided geometry (more geo on the plane) to achieve smooth curved profiles; vertices must sit below the arch curve line to avoid clipping"},{"t":"depth_cue_sightlines","f":"Partial visibility through bars/grates into adjacent spaces creates depth cues and player curiosity; the actual traversal path routes through a different building to reach the visible space"},{"t":"isometric_workflow","f":"For isometric 3D levels, start with a 2D sketch/map before creating a 3D blockout (simple walls, floors, ceilings) in Blender using cube with inverted normals and Ctrl+R loop cuts to extrude walls and cut windows."},{"t":"isometric_workflow","f":"Blender .blend files can be imported directly into Unity without FBX export; Ctrl+S in Blender or Photoshop triggers a live update in Unity, enabling a non-destructive back-and-forth workflow."},{"t":"isometric_workflow","f":"Adding small knife-tool cuts on top of simple boxy meshes makes low-poly stylized art look handmade and intentional, useful for isometric game assets that read well at camera distance."},{"t":"isometric_workflow","f":"Toon/cel shaders (e.g. Toony Colors Pro 2) strip specular, metallic, and normal map complexity, giving isometric scenes a flat stylized look that pairs well with simple geometry and solid color palettes."},{"t":"isometric_workflow","f":"Complex isometric scene objects decompose into primitive shapes: couches = squashed rectangles, tables = squashed cylinders, trees = stacked cones, characters = ovals \u2014 all colored via simple flat material assignments in Blender."},{"t":"city","f":"Road presets include lane configurations with sidewalk variants (e.g., 'two lane + sidewalks'); roads auto-align to landscape with configurable elevation offset and landscape layer masking (e.g., grass removal under roads)."},{"t":"city","f":"Road drawing uses click-to-place nodes for straight segments; holding Shift creates curved segments; middle mouse wheel adjusts elevation in real-time to create bridges and overpasses."},{"t":"city","f":"City kits are swappable asset packs (e.g., 'Modern City', 'Miami Bass') added to a level with one click; custom kits can be created with user-provided meshes and styles."},{"t":"city","f":"Blocks (building zones) are generated using a 'from edges' tool that automatically detects valid buildable areas by analyzing road edge geometry."},{"t":"city","f":"Plugin operates as a custom Editor Mode (Selection Mode > City Builder) with dedicated widget tabs for General, Roads, and Blocks, plus a simplified game-style UI toggle in settings."},{"t":"city","f":"Building props use a struct called 'prop spline points' storing 5 local points that generate a spline path around the building perimeter for fence/edge placement."},{"t":"city","f":"Spline mesh props use two mesh variants: a 'complete mesh' (both sides, used for the last segment) and an 'incomplete mesh' (one side, used for all other segments), with configurable mesh width, tangent length for curvature, and begin/end scale."},{"t":"city","f":"Spline mesh props have a configurable 'percent chance to spawn' (default 75% for fences), a tangent length controlling curvature, and support random material selection from a material list."},{"t":"city","f":"Edge props are individually placed along the building perimeter spline with configurable prop spacing, collision bounds, scale range, rotation, random yaw, and two-tier spawn probability: a global chance (e.g. 20% for pine trees on a house) and per-instance chance (e.g. 100% for each tree if global passes)."},{"t":"city","f":"Road props support spline and edge prop types with specific 'curves and segment settings' unique to roads, and all prop configurations can be loaded from a data table."},{"t":"city","f":"City grid size is controlled by X size and Z size parameters; setting both to 5 with scale 25 creates a walkable city block, while 20x20 at scale 200 generates a full city-scale layout"},{"t":"city","f":"Vertex snapping (V key) is used to align building pieces and prefabs to each other precisely when manually editing the generated city"},{"t":"city","f":"Generated city buildings are composed of individually editable modular pieces (walls, doors, flags) that can be deleted or repositioned post-generation"},{"t":"city","f":"City builder prefab is placed at origin (0,0,0) with initial scale 1,1,1 then scaled up (e.g. 25) to match the terrain size"},{"t":"city","f":"Global volume prefab from postprocesses folder is added for depth/lighting; environment skybox color is customized via Window > Rendering > Lighting panel"},{"t":"city","f":"The tool supports multiple building variations that are randomly selected during generation, providing visual variety across the city grid"},{"t":"city","f":"Road prefabs use a grid step of 38 units for discrete movement, ensuring no gaps form between road segments when snapping"},{"t":"city","f":"Road system height is set to 8.6 units and kept consistent across the entire road network"},{"t":"city","f":"Building block prefabs maintain constant pixel density, border geometry height, and window/floor sizes regardless of shape changes, allowing seamless assembly without UV adjustments"},{"t":"city","f":"Vertex snapping (V key) is used to precisely connect block prefabs to road edges by dragging outermost vertices together"},{"t":"city","f":"Two constructor systems are used: road constructor (Sci-Fi Road Constructor 38 inches folder) and city constructor (Sci-Fi City folder), each containing pre-configured prefabs"},{"t":"city","f":"Linear fog is used for optimization where camera clipping planes far distance and shadow distance match the fog range, and prefabs are marked static to avoid per-frame transforms at runtime"},{"t":"subscene_streaming","f":"Volume-based subscene loading uses two nested volumes: an outer 'preparation' volume for pre-loading scene data into memory, and an inner 'activation' volume that triggers the actual scene load. The activation volume must always be inside the preparation volume or the scene will not load."},{"t":"subscene_unloading","f":"Unload volumes are separate red-box trigger zones placed at exits. By changing 'amount of volumes' and setting type from 'load volume' to 'unload volume', a dedicated unload trigger is created that removes the subscene when the player passes through it."},{"t":"distance_based_loading","f":"Distance-based subscene loading uses a radius from center: the subscene loads when the player enters the range and automatically unloads when the player exits the range. Unlike volume-based loading, there is no separate pre-loading phase, making it optimal only for smaller subscenes."},{"t":"subscene_streaming","f":"Volume-based loading is configured by setting 'subscene loading mode' to 'volume based' in map settings via the subscene cogwheel icon, then setting 'amount of volumes' to define how many load/unload trigger zones exist per subscene."},{"t":"level_chunk_tooling","f":"An eye icon toggle allows hiding subscene geometry so designers can clearly see and position load/unload volumes or distance-based loaders without visual obstruction from the scene content itself."},{"t":"subscene_streaming","f":"Renaming a subscene automatically updates all associated load/unload volumes to reflect the new name, and renaming an entire map triggers a scene reload but preserves all volume configurations. No data is lost during rename operations."},{"t":"uv_unwrap","f":"Always apply scale (Ctrl+A > Scale) before unwrapping; unapplied scale skews UV proportions, distorting texture density across the mesh."},{"t":"uv_unwrap","f":"Use 'Project from View' (UV menu > 3D View > Project from View) as a clean-slate reset before marking seams, to eliminate inherited UV islands and seam artifacts from the modeling process."},{"t":"uv_seam_placement","f":"UV seams should prioritize minimizing distortion over minimizing seam count; place seams at natural geometry breaks (like clothing stitches or material boundaries) rather than trying to reduce them."},{"t":"uv_unwrap","f":"4-step UV workflow: (1) apply scale, (2) project UVs from view, (3) mark seams on edges using Edge mode (press 2) with Alt+Click for edge loops and Ctrl+Click for edge paths, (4) select all faces and unwrap."},{"t":"uv_seam_placement","f":"Triplanar mapping can blend across UV seams for procedural materials, reducing visible seam artifacts without manual texture painting, but should not replace proper unwrapping (avoid relying on cube projection alone)."},{"t":"uv_unwrap","f":"Clean topology with proper edge flow enables Alt+Click loop selection and Ctrl+Click path selection for fast seam marking; poor topology breaks these selection tools and complicates unwrapping."},{"t":"world_generation","f":"Gaia world generation uses a 4-step pipeline: 1) Create World Designer in Gaia Manager, 2) Generate world (stamps island onto terrain), 3) Spawn biomes, 4) Create runtime \u2014 producing a fully populated island"},{"t":"terrain","f":"Gaia stamps pre-generated island heightmaps directly onto Unity terrain, separating world shape generation from biome population"},{"t":"biome_placement","f":"Biome spawning is a distinct automated step that populates terrain with vegetation, textures, and objects after the base terrain is stamped"},{"t":"world_generation","f":"Gaia uses a runtime creation step as the final phase, converting the designed world into a playable game-ready environment"}];

// ── KEYWORD SEARCH (no vectors needed — fast & free) ────────────────────────
function queryKB(input, topN = 7) {
  const q = input.toLowerCase();
  const words = q.split(/\W+/).filter(w => w.length > 3);

  // Topic keyword map
  const TOPIC_TRIGGERS = {
    fps:       ['first person','fps','firstperson','look','mouselook','pointer lock'],
    tps:       ['third person','tps','follow camera','over shoulder','behind'],
    shooting:  ['shoot','gun','bullet','raycast','hitscan','weapon','fire','aim','ammo','reload','recoil'],
    water:     ['water','swim','ocean','river','lake','buoyancy','float','wave','underwater','pool'],
    dungeon:   ['dungeon','cave','underground','tunnel','basement','cellar','mine','dark room','corridor'],
    interior:  ['interior','inside','building','house','room','door','enter','exit','indoors'],
    city:      ['city','town','street','road','block','building','skyscraper','urban','traffic','grid'],
    npc:       ['npc','crowd','pedestrian','character','ai','enemy','citizen','person','people'],
    physics:   ['physics','gravity','mass','collision','rigid','bounce','force','velocity','friction'],
    vehicles:  ['car','vehicle','drive','truck','bus','wheel','suspension','traffic'],
    rendering: ['render','shadow','light','lod','performance','fps','frame','gpu','shader','fog'],
    camera:    ['camera','view','fov','perspective','zoom','spring arm','follow','smooth'],
  };

  // Score each chunk
  const scored = KB.map((chunk, i) => {
    let score = 0;
    const fact = chunk.f.toLowerCase();
    const topic = chunk.t.toLowerCase();

    // Word overlap with fact text
    words.forEach(w => { if (fact.includes(w)) score += 2; });

    // Topic trigger boost
    for (const [t, triggers] of Object.entries(TOPIC_TRIGGERS)) {
      if (triggers.some(tr => q.includes(tr))) {
        if (topic.startsWith(t)) score += 5;
      }
    }

    // Direct topic match boost
    if (topic.includes(q.split(' ')[0])) score += 3;

    return { ...chunk, score };
  });

  return scored
    .filter(c => c.score > 0)
    .sort((a,b) => b.score - a.score)
    .slice(0, topN)
    .map(c => `[${c.t}] ${c.f}`);
}

// ── SYSTEM PROMPT ────────────────────────────────────────────────────────────
const BASE_SYSTEM = `You are the AI brain of Crate Engine — a browser-based 3D game engine powered by Three.js.
You help users build game worlds, control NPCs, set up cameras, design interiors, build cities, and more.
You have two modes depending on the request type:

MODE 1 — COMMAND MODE (default): Convert user input into engine commands.
Return ONLY JSON: {"commands": ["cmd1", "cmd2"], "message": "brief friendly response", "mode": "command"}

MODE 2 — KNOWLEDGE MODE: When user asks HOW something works, wants technical info, or asks you to EXPLAIN.
Return JSON: {"commands": [], "message": "detailed helpful answer", "mode": "knowledge"}

AVAILABLE ENGINE COMMANDS:
- play as [character] — knight, adventurer, swat, king, punk, soldier, casual, farmer, suit, worker, witch, medieval, scifi, formal, beach, spacesuit
- equip [weapon] — sword, axe, rifle, pistol, shotgun, bow, spear, hammer, dagger, katana, shield, staff
- spawn [N] npcs / spawn [N] enemies / spawn npc woman / spawn npc man
- add [object] — buildings, trees, rocks, cars, boats, furniture, props (2000+ models available)
- build a city / build a dungeon / build a cave / build a house / build interior
- add water / add pool / add river / add ocean
- add first person camera / add third person camera / fps mode / tps mode
- terrain [type] — flat, hills, mountains, desert, island, canyon, volcano
- water [preset] — calm, tropical, stormy, arctic, blood, lava, crystal
- time [period] — dawn, sunrise, noon, sunset, dusk, night, midnight
- weather: make it rain / snow / fog / clear
- add swimming / add buoyancy / water physics
- add shooting / enable combat / add weapons system
- build city world / build downtown / add residential area / add roads
- add traffic / add ai cars / add pedestrians
- clear / save / load / heal / stats
- show [category] — weapons, buildings, characters, trees, animals, vehicles

RULES:
1. ALWAYS return valid JSON
2. Break complex requests into multiple commands
3. Be friendly and specific in the message
4. If user asks about physics values, implementation details, or how things work → use KNOWLEDGE MODE with the provided context
5. If totally unclear → ask a clarifying question in the message`;

function buildSystemPrompt(input, relevantFacts) {
  if (relevantFacts.length === 0) return BASE_SYSTEM;
  const context = `\n\n── RELEVANT KNOWLEDGE BASE ──\nUse these facts to inform your response with real values:\n${relevantFacts.map((f,i) => `${i+1}. ${f}`).join('\n')}\n──────────────────────────────`;
  return BASE_SYSTEM + context;
}

// ── CORS HEADERS ─────────────────────────────────────────────────────────────
const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'POST, GET, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type',
  'Content-Type': 'application/json',
};

// ── MAIN HANDLER ─────────────────────────────────────────────────────────────
export default {
  async fetch(request, env) {
    if (request.method === 'OPTIONS') return new Response(null, { headers: CORS });

    const url = new URL(request.url);

    // Health check / KB stats
    if (url.pathname === '/stats' || url.pathname === '/health') {
      return new Response(JSON.stringify({
        status: 'ok',
        kb_chunks: KB.length,
        topics: [...new Set(KB.map(c => c.t))].sort(),
      }), { headers: CORS });
    }

    // KB query endpoint (for debugging / future use)
    if (url.pathname === '/query-knowledge' && request.method === 'POST') {
      const { q } = await request.json();
      const results = queryKB(q || '', 10);
      return new Response(JSON.stringify({ query: q, results }), { headers: CORS });
    }

    if (request.method !== 'POST') return new Response('POST only', { status: 405 });

    try {
      const body = await request.json();
      const input = body.input || body.message || body.text || '';
      const apiKey = body.apiKey || env.OPENROUTER_API_KEY;
      const agentMode = body.agent === true || body.mode === 'agent'; // AI agent button path

      if (!input) {
        return new Response(JSON.stringify({ commands: [], message: 'What would you like to build?', mode: 'command' }), { headers: CORS });
      }

      // Retrieve relevant knowledge
      const relevantFacts = queryKB(input);
      const systemPrompt = buildSystemPrompt(input, relevantFacts);

      // No API key — run command directly without AI
      if (!apiKey) {
        return new Response(JSON.stringify({
          commands: [input],
          message: 'Running...',
          mode: 'command',
          kb_hits: relevantFacts.length,
        }), { headers: CORS });
      }

      // Call AI (OpenRouter → Gemini Flash free tier)
      const aiResponse = await fetch('https://openrouter.ai/api/v1/chat/completions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer ' + apiKey,
          'HTTP-Referer': 'https://crateshipgames.com',
          'X-Title': 'Crate Engine AI',
        },
        body: JSON.stringify({
          model: agentMode ? 'google/gemini-2.0-flash-thinking-exp:free' : 'google/gemini-2.0-flash-exp:free',
          max_tokens: agentMode ? 600 : 350,
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: input }
          ]
        })
      });

      if (!aiResponse.ok) {
        const err = await aiResponse.text();
        console.error('AI error:', err);
        return new Response(JSON.stringify({ commands: [input], message: 'Running...', mode: 'command' }), { headers: CORS });
      }

      const data = await aiResponse.json();
      const text = data.choices?.[0]?.message?.content || '{}';

      // Parse JSON response
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        const parsed = JSON.parse(jsonMatch[0]);
        parsed.kb_hits = relevantFacts.length; // debug info
        return new Response(JSON.stringify(parsed), { headers: CORS });
      }

      return new Response(JSON.stringify({ commands: [input], message: text.slice(0, 200), mode: 'command' }), { headers: CORS });

    } catch (err) {
      console.error(err);
      return new Response(JSON.stringify({ commands: [], message: 'Error: ' + err.message }), {
        status: 500, headers: CORS
      });
    }
  }
};
